SELECT CASE WHEN shipping_fee >= 40 THEN 'high' WHEN shipping_fee >= 19 THEN 'mid' ELSE 'low' END AS shipping_fee_bucket, MAX(shipping_fee) AS max_shipping_fee, MAX(order_date) AS last_order_date FROM orders WHERE shipping_fee > 12 AND status = 'CANCELLED' AND customer_id = 24 GROUP BY CASE WHEN shipping_fee >= 40 THEN 'high' WHEN shipping_fee >= 19 THEN 'mid' ELSE 'low' END HAVING max_shipping_fee >= 16 ORDER BY shipping_fee_bucket
